<script setup>
import {Head} from '@inertiajs/vue3';import {computed,ref} from 'vue';import AppShell from '@/Layouts/AppShell.vue';import SettingsNav from '@/Components/SettingsNav.vue';import PageHeader from '@/Components/PageHeader.vue';import UiAlert from '@/Components/UiAlert.vue';
const p=defineProps({section:String,balance:String,balanceUnits:Number,rates:Object,scale:Number,suggestions:Array,gstBasisPoints:Number,paymentConfigured:Boolean,entries:Object,unsupported:Object}),amount=ref(100),busy=ref(false),error=ref(''),status=ref('');const valid=computed(()=>Number.isInteger(+amount.value)&&+amount.value>=5&&+amount.value<=100000&&+amount.value%5===0),taxMinor=computed(()=>Math.ceil(+amount.value*100*p.gstBasisPoints/10000)),total=computed(()=>(+amount.value+taxMinor.value/100).toFixed(2));const rate=u=>`${u/p.scale}`.replace(/\.0$/,'');
function load(){return new Promise((ok,no)=>{if(window.Razorpay)return ok();let s=document.createElement('script');s.src='https://checkout.razorpay.com/v1/checkout.js';s.onload=ok;s.onerror=no;document.head.appendChild(s)})}async function add(){if(!valid.value||busy.value)return;busy.value=true;error.value='';status.value='';try{let key=crypto.randomUUID(),res=await fetch('/settings/wallet/top-ups',{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':document.querySelector('meta[name="csrf-token"]')?.content||''},body:JSON.stringify({amount_rupees:+amount.value,idempotency_key:key})}),data=await res.json();if(!res.ok)throw data;await load();new window.Razorpay({...data,handler:()=>{status.value='Payment received. Awaiting secure confirmation.'},modal:{ondismiss:()=>status.value='Payment was cancelled. No credits were added.'}}).open()}catch(e){error.value=e.errors?.amount_rupees?.[0]||e.message||'Unable to start checkout.'}finally{busy.value=false}}
</script>
<template><AppShell><Head title="LensPic Wallet"/><div class="lp-page"><PageHeader eyebrow="Settings" title="LensPic Wallet" description="Add and use account-owned LensPic credits."/><div class="mt-8 grid gap-6 lg:grid-cols-[240px_1fr]"><SettingsNav :section="section"/><main class="space-y-6"><section class="lp-card p-6" aria-live="polite"><p class="eyebrow">Balance</p><h2 class="mt-2 text-4xl font-bold">{{balance}} credits</h2><p class="mt-2 text-sm text-slate-600">₹1 = 1 credit</p></section><section class="lp-card space-y-5 p-6"><div><h2 class="text-xl font-bold">Add Credit</h2><p class="lp-subtitle">Add credits in multiples of ₹5. We suggest ₹100+ to reduce frequent top-ups.</p></div><UiAlert v-if="!paymentConfigured" tone="warning">Razorpay checkout is not configured. Credits cannot be added.</UiAlert><label class="lp-label" for="wallet-amount">Amount<div class="field mt-2 flex items-center gap-2"><span>₹</span><input id="wallet-amount" v-model.number="amount" type="number" min="5" max="100000" step="5" class="min-w-0 flex-1 bg-transparent outline-none" aria-describedby="wallet-calculation wallet-error"><span>= {{valid?amount:0}} credits</span></div></label><p id="wallet-error" class="text-sm text-rose-600">{{!valid?'Enter an amount in multiples of ₹5.':error}}</p><div class="flex flex-wrap gap-2"><button v-for="v in suggestions" type="button" class="btn-secondary" :aria-pressed="amount===v" :class="{'ring-2 ring-indigo-500':amount===v}" @click="amount=v">₹{{v}}</button></div><dl id="wallet-calculation" class="grid gap-3 rounded-xl bg-slate-50 p-4 sm:grid-cols-4" aria-live="polite"><div><dt>Wallet value</dt><dd class="font-semibold">₹{{valid?amount:0}}</dd></div><div><dt>GST/tax</dt><dd class="font-semibold">₹{{valid?(taxMinor/100).toFixed(2):'0.00'}}</dd></div><div><dt>Total payable</dt><dd class="font-semibold">₹{{valid?total:'0.00'}}</dd></div><div><dt>Credits</dt><dd class="font-semibold">{{valid?amount:0}}</dd></div></dl><p class="text-sm text-slate-500">Tax/GST will be added using the configured billing rate.</p><button class="btn-primary" :disabled="!valid||!paymentConfigured||busy" @click="add">{{busy?'Starting…':'Add'}}</button><UiAlert v-if="status">{{status}}</UiAlert></section>
<section class="lp-card p-6"><h2 class="text-xl font-bold">How to use credits</h2><div class="mt-5 grid gap-4 md:grid-cols-2"><article class="rounded-xl border p-5"><h3 class="font-bold">Mail</h3><p>{{rate(rates.mail_notification_units)}} credit/notification</p><p class="mt-3 text-sm text-slate-500">{{unsupported.mail}}</p></article><article class="rounded-xl border p-5"><h3 class="font-bold">WhatsApp notifications · Coming soon</h3><p class="mt-2 text-sm">Automated photo upload and welcome messages are unavailable. No credits are charged.</p><p class="mt-3 text-sm text-slate-500">{{unsupported.whatsapp}}</p></article><article class="rounded-xl border p-5"><h3 class="font-bold">Liveness Detection</h3><p>Reject Fake Selfies using Liveness Detection</p><p class="font-semibold">{{rate(rates.liveness_check_units)}} credits/guest</p><a href="/settings/privacy" class="mt-3 inline-block text-indigo">Learn More</a><p class="mt-3 text-sm text-slate-500">{{unsupported.liveness}}</p></article><article class="rounded-xl border p-5"><h3 class="font-bold">Subscription</h3><p>Buy & Renew Subscriptions</p><p>Unlock premium features</p><div class="mt-3 flex gap-3"><a href="/pricing" class="text-indigo">View Plans</a><a href="mailto:hello@lenspic.in" class="text-indigo">Contact Support</a></div><p class="mt-3 text-sm text-slate-500">{{unsupported.subscription}}</p></article></div></section>
<section class="lp-card p-6"><div class="flex flex-wrap items-center justify-between gap-3"><h2 class="text-xl font-bold">Wallet Statement</h2><a href="/settings/transactions?tab=wallet" class="text-sm font-semibold text-indigo">View Wallet Transactions</a></div><div v-if="entries.data.length" class="lp-table-wrap mt-5"><table class="lp-table"><thead><tr><th>Date</th><th>Description</th><th>Added</th><th>Used</th><th>Reference</th><th>Balance</th></tr></thead><tbody><tr v-for="e in entries.data" :key="e.id"><td>{{new Date(e.date).toLocaleDateString('en-IN')}}</td><td>{{e.description}}</td><td>{{e.added||'—'}}</td><td>{{e.used||'—'}}</td><td>{{e.reference}}</td><td>{{e.balance}}</td></tr></tbody></table></div><p v-else class="mt-4 text-sm text-slate-500">No Wallet activity yet.</p><div class="mt-4 flex gap-2"><a v-for="l in entries.links" :href="l.url||'#'" class="btn-secondary" :class="{'opacity-50 pointer-events-none':!l.url}">{{l.label}}</a></div></section></main></div></div></AppShell></template>
